import java.nio.file.NoSuchFileException;
import java.io.IOException;

public class Repro {
    void foo() {
        try {
            Files.delete("example.txt");
        } catch (NoSuchFileException e) {
            // Unrecoverable error
            throw e;
        } catch (IOException e) {
            // Potentially recoverable error. Sleep and try again...
        }
    }
}

import java.nio.file.NoSuchFileException;

public class Foo {
